resize() {
  const parent = this.canvas.parentElement;
  let target = this.size;
  if (parent) {
    const style = window.getComputedStyle(parent);
    const available = parent.clientWidth - parseFloat(style.paddingLeft||0) - parseFloat(style.paddingRight||0);
    if (available > 0) target = Math.min(available, this.maxSize);
  }
  target = Math.max(280, Math.floor(target));
  const dpr = window.devicePixelRatio || 1;
  this.cssSize = target;
  this.canvas.style.width = target + 'px';
