  this.canvas.width = Math.round(target * dpr);
  this.canvas.height = Math.round(target * dpr);
  this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  this.dpr = dpr;
  this.padding = target * 0.062;
  this.cell = (target - this.padding * 2) / (this.board.size - 1);
}
```
