// 1) 空盘首手（最复杂的搜索场景），检查是否 <= 2000ms
{
  const b = new Board();
  const e = new AIEngine("hard");
  const t0 = Date.now();
  const mv = await e.chooseMove(b, BLACK);
  console.log("[empty] move:", JSON.stringify(mv), "elapsed:", Date.now()-t0, "stats:", JSON.stringify(e.lastStats));
}

