/** headless Chrome + CDP 端到端冒烟测试 */
import fs from "node:fs";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const targets = await (await fetch("http://localhost:9222/json/list")).json();
const page = targets.find((t) => t.type === "page" && t.url.includes("8123"));
if (!page) {
  console.log("no page target", JSON.stringify(targets.map((t) => t.url), null, 2));
  process.exit(1);
}

const ws = new WebSocket(page.webSocketDebuggerUrl);
let nextId = 1;
const pending = new Map();
const consoleErrors = [];
const pageErrors = [];

ws.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) reject(new Error(JSON.stringify(msg.error)));
    else resolve(msg.result);
    return;
  }
  if (msg.method === "Runtime.consoleAPICalled" && msg.params.type === "error") {
    consoleErrors.push(msg.params.args.map((a) => a.value ?? a.description).join(" "));
  }
  if (msg.method === "Runtime.exceptionThrown") {
    pageErrors.push(msg.params.exceptionDetails.exception?.description || "exception");
  }
});

function send(method, params = {}) {
  const id = nextId++;
  ws.send(JSON.stringify({ id, method, params }));
  return new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
}

async function evaluate(expression) {
  const result = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (result.exceptionDetails) throw new Error("eval failed: " + JSON.stringify(result.exceptionDetails));
  return result.result.value;
}

async function click(x, y) {
  await send("Input.dispatchMouseEvent", { type: "mousePressed", x, y, button: "left", clickCount: 1 });
  await send("Input.dispatchMouseEvent", { type: "mouseReleased", x, y, button: "left", clickCount: 1 });
}

await new Promise((resolve) => ws.addEventListener("open", resolve));
await send("Runtime.enable");
await send("Page.enable");

let pass = 0;
let fail = 0;
const check = (name, ok, extra = "") => {
  if (ok) { pass++; console.log("  PASS  " + name); }
  else { fail++; console.log("  FAIL  " + name + " " + extra); }
};

let ready = false;
for (let i = 0; i < 50 && !ready; i++) {
  try { ready = await evaluate("!!window.__GOMOKU_READY__"); } catch (e) {}
  if (!ready) await sleep(200);
}
check("ES Module 加载并完成初始化", ready === true);
check("没有未捕获异常", pageErrors.length === 0, JSON.stringify(pageErrors));
check("没有 console.error", consoleErrors.length === 0, JSON.stringify(consoleErrors));

const info = await evaluate(`(() => {
  const app = window.gomoku;
  const c = document.getElementById("board-canvas");
  const r = c.getBoundingClientRect();
  return {
    canvasW: Math.round(r.width), canvasH: Math.round(r.height),
    cssW: c.style.width, cell: app.renderer.cell, pad: app.renderer.padding,
    rectLeft: r.left, rectTop: r.top,
    history: document.getElementById("history-list").textContent.trim(),
    status: document.getElementById("status-text").textContent,
    bootHidden: document.getElementById("boot-warning").hidden,
    moveCount: app.game.moveCount,
  };
})()`);
check("Canvas 已按容器自适应尺寸", info.canvasW > 250 && info.cssW.length > 0, JSON.stringify(info));
check("启动时未弹出模块加载警告", info.bootHidden === true);
check("初始手数为 0", info.moveCount === 0);
console.log("        " + JSON.stringify(info));

const toClient = (r, c) => ({ x: info.rectLeft + info.pad + c * info.cell, y: info.rectTop + info.pad + r * info.cell });

// 1) 真实点击落子 -> AI 回应
{
  const p = toClient(7, 7);
  await click(p.x, p.y);
  await sleep(150);
  const after = await evaluate("window.gomoku.game.moveCount");
  check("点击交叉点成功落子", after === 1, "moveCount=" + after);
  await sleep(2000);
  const s = await evaluate("({ count: window.gomoku.game.moveCount, status: window.gomoku.game.status, turn: window.gomoku.game.currentPlayer })");
  check("AI 在玩家落子后自动回应", s.count === 2, JSON.stringify(s));
  check("AI 落子后轮次回到玩家", s.turn === 1 && s.status === "playing", JSON.stringify(s));
}

// 2) 非法落点提示
{
  const occupied = toClient(7, 7);
  await click(occupied.x, occupied.y);
  const toast = await evaluate(`({ hidden: document.getElementById("toast").hidden, text: document.getElementById("toast").textContent })`);
  check("重复落子被拒绝并提示", toast.hidden === false && toast.text.includes("已经有棋子"), JSON.stringify(toast));

  await click(info.rectLeft + 2, info.rectTop + 2);
  const t2 = await evaluate(`document.getElementById("toast").textContent`);
  check("棋盘外点击给出提示", t2.includes("交叉点"), t2);
}

// 3) 悔棋
{
  const before = await evaluate("window.gomoku.game.moveCount");
  await evaluate(`document.getElementById("btn-undo").click()`);
  await sleep(200);
  const after = await evaluate("({ count: window.gomoku.game.moveCount, turn: window.gomoku.game.currentPlayer })");
  check("悔棋一次回退双方各一手", before === 2 && after.count === 0, JSON.stringify({ before, after }));
  check("悔棋后轮到玩家", after.turn === 1, JSON.stringify(after));
}

// 4) 每步计时
{
  await evaluate(`document.getElementById("toggle-turn-timer").click()`);
  await sleep(50);
  const shown = await evaluate(`!document.getElementById("stat-turn-row").hidden`);
  check("开启每步计时后显示本步用时", shown === true);
  await evaluate(`document.getElementById("toggle-turn-timer").click()`);
}

// 5) 双人模式
{
  await evaluate(`document.querySelector('[data-mode="pvp"]').click()`);
  await sleep(200);
  const p1 = toClient(3, 3);
  await click(p1.x, p1.y);
  await sleep(150);
  const p2 = toClient(4, 4);
  await click(p2.x, p2.y);
  await sleep(150);
  const s = await evaluate("({ count: window.gomoku.game.moveCount, turn: window.gomoku.game.currentPlayer, dot: document.getElementById('turn-dot').dataset.player })");
  check("双人模式两人轮流落子", s.count === 2 && s.turn === 1, JSON.stringify(s));
  const disabled = await evaluate(`document.querySelector('[data-difficulty="hard"]').disabled`);
  check("双人模式下难度按钮禁用", disabled === true);
}

// 6) 结算 + 棋谱 + 复盘
{
  await evaluate(`document.querySelector('[data-mode="pve"]').click()`);
  await sleep(200);
  await evaluate(`(() => {
    const g = window.gomoku.game;
    g.board.reset();
    [[7,3,1],[7,4,1],[7,5,1],[7,6,1],[0,0,2],[0,1,2],[0,2,2]].forEach(([r,c,p]) => g.board.place(r,c,p));
    g.currentPlayer = 1; g.status = "playing"; g.winner = null; g.winLine = null;
    g.emitChange();
  })()`);
  const win = toClient(7, 7);
  await click(win.x, win.y);
  await sleep(500);
  const r = await evaluate(`({
    modalHidden: document.getElementById("result-modal").hidden,
    title: document.getElementById("result-title").textContent,
    moves: document.getElementById("result-moves").textContent,
    time: document.getElementById("result-time").textContent,
    winner: window.gomoku.game.winner,
    winLine: window.gomoku.game.winLine ? window.gomoku.game.winLine.length : 0,
    historyCount: document.querySelectorAll("#history-list .history__item").length,
  })`);
  check("获胜后弹出结算画面", r.modalHidden === false, JSON.stringify(r));
  check("结算显示胜方", r.title.includes("黑棋胜"), r.title);
  check("结算显示手数与用时", r.moves.includes("手") && /\d\d:\d\d/.test(r.time), JSON.stringify(r));
  check("获胜五子被高亮连线", r.winLine >= 5, String(r.winLine));
  check("棋谱写入本地列表", r.historyCount >= 1, String(r.historyCount));

  const rect2 = await evaluate(`(() => { const b = document.getElementById("board-canvas").getBoundingClientRect(); return { left: b.left, top: b.top }; })()`);
  await click(rect2.left + info.pad + 10 * info.cell, rect2.top + info.pad + 10 * info.cell);
  const endState = await evaluate("({ count: window.gomoku.game.moveCount, status: window.gomoku.game.status })");
  check("对局结束后不能继续落子", endState.status === "over" && endState.count === 7, JSON.stringify(endState));

  await evaluate(`document.querySelector("#history-list .history__item").click()`);
  await sleep(400);
  const replay = await evaluate(`({ hidden: document.getElementById("replay-modal").hidden, info: document.getElementById("replay-info").textContent, meta: document.getElementById("replay-meta").textContent })`);
  check("点击棋谱打开复盘", replay.hidden === false, JSON.stringify(replay));
  check("复盘显示手数", replay.info.includes("7"), replay.info);

  await evaluate(`document.getElementById("replay-first").click()`);
  await sleep(120);
  const first = await evaluate(`document.getElementById("replay-info").textContent`);
  check("复盘可回到开局", first.includes("第 0"), first);

  await evaluate(`document.getElementById("replay-next").click()`);
  await sleep(120);
  const nextText = await evaluate(`document.getElementById("replay-info").textContent`);
  check("复盘可单步前进", nextText.includes("第 1"), nextText);

  await evaluate(`document.getElementById("replay-play").click()`);
  await sleep(1400);
  await evaluate(`document.getElementById("replay-play").click()`);
  await evaluate(`document.getElementById("btn-replay-close").click()`);
  await sleep(150);
  check("复盘可关闭", (await evaluate(`document.getElementById("replay-modal").hidden`)) === true);
}

// 7) 刷新恢复
{
  await evaluate(`document.getElementById("btn-result-undo").click()`);
  await sleep(300);
  const undone = await evaluate("({ count: window.gomoku.game.moveCount, status: window.gomoku.game.status })");
  check("结束后可悔棋继续", undone.status === "playing", JSON.stringify(undone));

  await send("Page.reload", { ignoreCache: false });
  await sleep(2500);
  const restored = await evaluate("({ ready: !!window.__GOMOKU_READY__, count: window.gomoku.game.moveCount, status: window.gomoku.game.status })");
  check("刷新后恢复未完成对局", restored.ready && restored.count === undone.count, JSON.stringify(restored));
  console.log("        刷新前 " + undone.count + " 手 -> 刷新后 " + restored.count + " 手");
}

check("全程无未捕获异常", pageErrors.length === 0, JSON.stringify(pageErrors));
check("全程无 console.error", consoleErrors.length === 0, JSON.stringify(consoleErrors));

const shot = await send("Page.captureScreenshot", { format: "png" });
fs.writeFileSync("tools/_shot.png", Buffer.from(shot.data, "base64"));
