  check("AI 开始思考（界面显示思考态）", mid.status === "thinking" && mid.overlay === true, JSON.stringify(mid));
  const rejected = await evaluate(`(() => { window.gomoku.handleHumanMove(0, 0); return { count: window.gomoku.game.moveCount, toast: document.getElementById("toast").textContent }; })()`);
  check("思考期间落子被拒绝并提示", rejected.count === 1 && rejected.toast.includes("思考"), JSON.stringify(rejected));
