import fs from "node:fs";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const targets = await (await fetch("http://localhost:9222/json/list")).json();
const page = targets.find((t) => t.type === "page" && t.url.includes("8123"));
const ws = new WebSocket(page.webSocketDebuggerUrl);
let id = 1; const pending = new Map();
ws.addEventListener("message", (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m.result); pending.delete(m.id); } });
const send = (method, params = {}) => { const i = id++; ws.send(JSON.stringify({ id: i, method, params })); return new Promise((r) => pending.set(i, r)); };
const evaluate = async (expression) => (await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true })).result.value;
const shoot = async (name) => { const s = await send("Page.captureScreenshot", { format: "png" }); fs.writeFileSync("tools/_" + name + ".png", Buffer.from(s.data, "base64")); };
await new Promise((r) => ws.addEventListener("open", r));
await send("Runtime.enable"); await send("Page.enable");

// 结算画面
await evaluate(`(() => {
  const g = window.gomoku.game;
  g.board.reset();
  const seq = [[7,3,1],[0,0,2],[7,4,1],[0,1,2],[7,5,1],[0,2,2],[7,6,1],[0,3,2],[7,7,1]];
  seq.forEach(([r,c,p]) => g.board.place(r,c,p));
  g.status = "playing"; g.currentPlayer = 2; g.winLine = null; g.emitChange();
})()`);
await sleep(200);
await evaluate(`window.gomoku.handleHumanMove(7, 7)`);
await sleep(700);
await shoot("win");
console.log("win state:", JSON.stringify(await evaluate(`({ status: window.gomoku.game.status, modal: getComputedStyle(document.getElementById("result-modal")).display, line: window.gomoku.game.winLine && window.gomoku.game.winLine.length })`)));

// 复盘画面
await evaluate(`document.querySelector("#history-list .history__item").click()`);
await sleep(600);
await evaluate(`document.getElementById("replay-range").value = 5; document.getElementById("replay-range").dispatchEvent(new Event("input"))`);
await sleep(300);
await shoot("replay");
console.log("replay:", await evaluate(`document.getElementById("replay-info").textContent`));

// 窄屏
await send("Emulation.setDeviceMetricsOverride", { width: 430, height: 900, deviceScaleFactor: 2, mobile: true });
await evaluate(`document.getElementById("btn-replay-close").click()`);
await sleep(300);
await shoot("mobile");
console.log("ok");
ws.close();
